// ZeroTrace FreeRTOS Main Task & Mode Dispatcher
void app_main() {
    initHardwareBus(); // Initialize SPI, I2C, ADC & ST7735
    initUSBHIDStack(); // Initialize USB OTG peripheral in HID mode

    xTaskCreatePinnedToCore(
        taskDisplayTelemetry,
        "DisplayTask",
        4096,
        NULL,
        2,
        &displayTaskHandle,
        1
    );

    xTaskCreatePinnedToCore(
        taskRFScannerAuditor,
        "RFScanTask",
        8192,
        NULL,
        3,
        &rfTaskHandle,
        0
    );
}
